# generated by tools/ail2py.py from integer_map_main.ail; edit the .ail until onelang s16
from integer_map import *
from file_identity import *
from ail import read_bytes, write_bytes
import sys

def main() -> int:
    if len(sys.argv) != 3:
        print('usage: integer_map input-path output-path', file=sys.stderr)
        return 2
    try:
        input: str = sys.argv[1]
        output: str = sys.argv[2]
        if input == output:
            raise ValueError
        if file_paths_same(input, output):
            raise ValueError
        data: bytes = read_bytes(input)
        text: str = data.decode()
        values: dict[str, int] = integer_map_from_tsv(text)
        report: str = integer_map_render(values)
        write_bytes(output, report.encode())
        return 0
    except ValueError:
        print('invalid integer map data or output aliases input', file=sys.stderr)
        return 2
    except IndexError:
        print('invalid integer map columns', file=sys.stderr)
        return 2
    except OSError:
        print('integer map file error', file=sys.stderr)
        return 2
    return 0

if __name__ == "__main__":
    sys.exit(main())
